use super::*;

/// Parse ONE clean import-statement text into 1–2 [`ImportSpec`]s (a `default, { named }` statement
/// yields two, one per shape, sharing the `from`). Whitespace is normalized first so a multi-line
/// clause parses the same as a single-line one.
pub(crate) fn parse_statement(stmt: &str) -> Vec<ImportSpec> {
    let norm = normalize_ws(stmt);
    let s = norm.trim().trim_end_matches(';').trim();
    let rest = match s.strip_prefix("import") {
        Some(r) => r.trim_start(),
        None => return Vec::new(),
    };
    // `import type …`
    let (type_only, rest) = match rest.strip_prefix("type ") {
        Some(r) => (true, r.trim_start()),
        None => (false, rest),
    };
    // side-effect: `import "x"` — no clause, just the source.
    if rest.starts_with('"') || rest.starts_with('\'') {
        return match quoted(rest) {
            Some(from) => vec![ImportSpec {
                from,
                symbols: Vec::new(),
                type_only,
                kind: "side-effect".to_string(),
            }],
            None => Vec::new(),
        };
    }
    // Otherwise: `<clause> from "<source>"`. The source is the final quoted string; the ` from `
    // keyword sits just before it (rfind is robust to a symbol literally named `from`).
    let from = match quoted_last(rest) {
        Some(f) => f,
        None => return Vec::new(),
    };
    let clause = match rest.rfind(" from ") {
        Some(i) => rest[..i].trim(),
        None => return Vec::new(),
    };
    parse_clause(clause, &from, type_only)
}
